package com.fasterxml.jackson.databind.type;

import com.fasterxml.jackson.databind.JavaType;
import com.fasterxml.jackson.databind.type.BasicType;
import java.io.*;
import java.lang.reflect.TypeVariable;
import java.math.*;
import java.util.*;
import java.util.Collection;
import java.util.List;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;

/**
 * Unit tests for CollectionType.construct
 */
public class CollectionType_construct_TriageGen1Test {

    @Test
    public void testConstruct_WithListAndString() {
        // Arrange
        Class<?> rawType = List.class;
        JavaType elemType = BasicType.fromStringType(String.class);

        // Act
        // Note: The provided source code has a hardcoded 'if (true)' block, 
        // which forces the use of TypeBindings.emptyBindings().
        CollectionType result = CollectionType.construct(rawType, elemType);

        // Assert
        assertNotNull("Result should not be null", result);
        assertEquals("Raw type should match", rawType, result.getRawClass());
        assertEquals("Element type should match", elemType, result.getContentType());
        // Since the code uses TypeBindings.emptyBindings(), we check for that behavior
        assertEquals("toString should represent the constructed type", 
                "List<java.lang.String>", result.toString());
    }

    @Test
    public void testConstruct_WithCollectionAndInteger() {
        // Arrange
        Class<?> rawType = Collection.class;
        JavaType elemType = BasicType.fromStringType(Integer.class);

        // Act
        CollectionType result = CollectionType.construct(rawType, elemType);

        // Assert
        assertNotNull(result);
        assertEquals(rawType, result.getRawClass());
        assertEquals(elemType, result.getContentType());
        assertEquals("Collection<int>", result.toString().replace("java.lang.Integer", "int"));
    }

    @Test
    public void testConstruct_WithGenericRawType() {
        // Arrange
        // Testing with a class that has type parameters to ensure TypeVariable extraction works
        Class<?> rawType = List.class;
        JavaType elemType = BasicType.fromStringType(Object.class);

        // Act
        CollectionType result = CollectionType.construct(rawType, elemType);

        // Assert
        assertNotNull(result);
        assertEquals(rawType, result.getRawClass());
        assertEquals(elemType, result.getContentType());
    }

    @Test
    public void testConstruct_RefineAndWithContentType() {
        // Arrange
        Class<?> rawType = List.class;
        JavaType elemType = BasicType.fromStringType(String.class);
        CollectionType result = CollectionType.construct(rawType, elemType);

        // Act
        CollectionType refined = result.withContentType(BasicType.fromStringType(Double.class));

        // Assert
        assertNotNull(refined);
        assertEquals(BasicType.fromStringType(Double.class), refined.getContentType());
        assertEquals(rawType, refined.getRawClass());
    }
}
